import java.util.*;class Solution{List<List<String>>o=new ArrayList<>();void f(int n,int r,int c,int d1,int d2,char[][]b){if(r==n){List<String>x=new ArrayList<>();for(char[]q:b)x.add(new String(q));o.add(x);return;}int a=((1<<n)-1)&~(c|d1|d2);while(a!=0){int bit=a&-a;a-=bit;int col=Integer.numberOfTrailingZeros(bit);b[r][col]='Q';f(n,r+1,c|bit,(d1|bit)<<1,(d2|bit)>>1,b);b[r][col]='.';}}public List<List<String>> solveNQueens(int n){char[][]b=new char[n][n];for(char[]r:b)Arrays.fill(r,'.');f(n,0,0,0,0,b);return o;}}
